# Tests for secret-rotation-validator.sh — red/green TDD.
#
# Two layers of coverage:
#   1. Pure-function unit tests: the script is sourced and its helpers
#      (days_between, classify_secret) are exercised in isolation.
#   2. CLI behaviour tests: the script is executed end-to-end against fixtures.

setup() {
  SCRIPT="$BATS_TEST_DIRNAME/../secret-rotation-validator.sh"
  FIXTURES="$BATS_TEST_DIRNAME/fixtures"
  # Source for the pure-function tests. The script guards main() behind a
  # sourced-vs-executed check, so sourcing does not run the CLI.
  # shellcheck source=/dev/null
  source "$SCRIPT"
}

# ---------------------------------------------------------------------------
# Pure function: days_between
# ---------------------------------------------------------------------------

@test "days_between counts whole days across months" {
  run days_between "2026-01-01" "2026-06-26"
  [ "$status" -eq 0 ]
  [ "$output" -eq 176 ]
}

@test "days_between is zero for identical dates" {
  run days_between "2026-06-26" "2026-06-26"
  [ "$status" -eq 0 ]
  [ "$output" -eq 0 ]
}

# ---------------------------------------------------------------------------
# Pure function: classify_secret <last_rotated> <policy> <warning> <now>
# ---------------------------------------------------------------------------

@test "classify_secret: overdue secret is expired" {
  run classify_secret "2026-01-01" 90 14 "2026-06-26"
  [ "$output" = "expired" ]
}

@test "classify_secret: within warning window is warning" {
  run classify_secret "2026-05-01" 60 14 "2026-06-26"
  [ "$output" = "warning" ]
}

@test "classify_secret: comfortably fresh is ok" {
  run classify_secret "2026-06-20" 365 14 "2026-06-26"
  [ "$output" = "ok" ]
}

@test "classify_secret boundary: age exactly equals policy is expired" {
  # 2026-03-28 + 90 days == 2026-06-26, so age == policy.
  run classify_secret "2026-03-28" 90 0 "2026-06-26"
  [ "$output" = "expired" ]
}

# ---------------------------------------------------------------------------
# CLI: JSON output
# ---------------------------------------------------------------------------

@test "json: past-due secret has status expired" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 14 --format json
  [ "$status" -eq 0 ]
  echo "$output" | jq -e '.secrets[] | select(.name=="db-password") | .status == "expired"'
}

@test "json: soon-to-expire secret has status warning" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 14 --format json
  [ "$status" -eq 0 ]
  echo "$output" | jq -e '.secrets[] | select(.name=="api-key") | .status == "warning"'
}

@test "json: far-future secret has status ok" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 14 --format json
  [ "$status" -eq 0 ]
  echo "$output" | jq -e '.secrets[] | select(.name=="tls-cert") | .status == "ok"'
}

@test "json: summary is grouped by urgency" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 14 --format json
  [ "$status" -eq 0 ]
  echo "$output" | jq -e '.summary.expired == 1'
  echo "$output" | jq -e '.summary.warning == 1'
  echo "$output" | jq -e '.summary.ok == 1'
}

@test "json: days_until_due is exposed per secret" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 14 --format json
  [ "$status" -eq 0 ]
  # api-key: 2026-05-01 + 60 days = 2026-06-30 => 4 days until due.
  echo "$output" | jq -e '.secrets[] | select(.name=="api-key") | .days_until_due == 4'
}

@test "json: configurable warning window reclassifies ok -> warning" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 400 --format json
  [ "$status" -eq 0 ]
  echo "$output" | jq -e '.secrets[] | select(.name=="tls-cert") | .status == "warning"'
}

@test "json: empty config yields zero counts" {
  run "$SCRIPT" --config "$FIXTURES/empty.json" --format json
  [ "$status" -eq 0 ]
  echo "$output" | jq -e '.summary.expired == 0'
  echo "$output" | jq -e '.secrets | length == 0'
}

# ---------------------------------------------------------------------------
# CLI: markdown output
# ---------------------------------------------------------------------------

@test "markdown: has report header and urgency sections" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 14 --format markdown
  [ "$status" -eq 0 ]
  [[ "$output" == *"# Secret Rotation Report"* ]]
  [[ "$output" == *"## Expired (1)"* ]]
  [[ "$output" == *"## Warning (1)"* ]]
  [[ "$output" == *"## OK (1)"* ]]
}

@test "markdown: lists the expired secret with its required-by services" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26 \
      --warning-days 14 --format markdown
  [ "$status" -eq 0 ]
  [[ "$output" == *"| db-password |"* ]]
  [[ "$output" == *"api, worker"* ]]
}

@test "markdown is the default format" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now 2026-06-26
  [ "$status" -eq 0 ]
  [[ "$output" == *"# Secret Rotation Report"* ]]
}

# ---------------------------------------------------------------------------
# CLI: error handling
# ---------------------------------------------------------------------------

@test "errors when --config is missing" {
  run "$SCRIPT" --now 2026-06-26
  [ "$status" -eq 2 ]
  [[ "$output" == *"no --config file provided"* ]]
}

@test "errors when config file does not exist" {
  run "$SCRIPT" --config /nonexistent/secrets.json
  [ "$status" -eq 2 ]
  [[ "$output" == *"config file not found"* ]]
}

@test "errors on invalid JSON config" {
  run "$SCRIPT" --config "$FIXTURES/invalid.json"
  [ "$status" -eq 2 ]
  [[ "$output" == *"not valid JSON"* ]]
}

@test "errors on unknown argument" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --bogus
  [ "$status" -eq 2 ]
  [[ "$output" == *"unknown argument"* ]]
}

@test "errors on invalid --format" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --format xml
  [ "$status" -eq 2 ]
  [[ "$output" == *"unknown format"* ]]
}

@test "errors on non-numeric --warning-days" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --warning-days abc
  [ "$status" -eq 2 ]
  [[ "$output" == *"must be a non-negative integer"* ]]
}

@test "errors on invalid --now date" {
  run "$SCRIPT" --config "$FIXTURES/secrets.json" --now not-a-date
  [ "$status" -eq 2 ]
  [[ "$output" == *"invalid --now date"* ]]
}

@test "--help prints usage and exits 0" {
  run "$SCRIPT" --help
  [ "$status" -eq 0 ]
  [[ "$output" == *"Usage:"* ]]
}

