#!/usr/bin/env bats
#
# Workflow structure tests.
#
# These run on the host (not through act). They verify that the workflow YAML
# is well-formed, has the expected triggers/jobs/steps, references the script
# and config that actually exist on disk, and passes actionlint.
#
# Kept under harness/ (not tests/) so the in-container `bats tests/` step never
# tries to execute them — they need actionlint and the repo layout on the host.

setup() {
  ROOT="${BATS_TEST_DIRNAME}/.."
  WF="${ROOT}/.github/workflows/secret-rotation-validator.yml"
}

@test "workflow file exists" {
  [ -f "$WF" ]
}

@test "actionlint passes cleanly (exit 0)" {
  run actionlint "$WF"
  [ "$status" -eq 0 ]
}

@test "workflow declares all expected trigger events" {
  for ev in "push:" "pull_request:" "schedule:" "workflow_dispatch:"; do
    grep -qE "^\s*${ev}" "$WF"
  done
}

@test "workflow defines the test and report jobs" {
  grep -qE "^\s{2}test:" "$WF"
  grep -qE "^\s{2}report:" "$WF"
}

@test "report job depends on the test job" {
  # The report job must declare 'needs: test' so reports only run after tests.
  grep -qE "needs:\s*test" "$WF"
}

@test "workflow sets least-privilege read permissions" {
  grep -qE "permissions:" "$WF"
  grep -qE "contents:\s*read" "$WF"
}

@test "workflow uses pinned actions/checkout@v4" {
  grep -qE "uses:\s*actions/checkout@v4" "$WF"
}

@test "workflow references the validator script, and it exists" {
  grep -q "secret-rotation-validator.sh" "$WF"
  [ -f "${ROOT}/secret-rotation-validator.sh" ]
}

@test "workflow's CONFIG_FILE path exists on disk" {
  # Extract the CONFIG_FILE env value and assert the file is present.
  local cfg
  cfg=$(grep -E "CONFIG_FILE:" "$WF" | head -1 | sed -E 's/.*CONFIG_FILE:\s*//' | tr -d '"'"'"' \r')
  [ -n "$cfg" ]
  [ -f "${ROOT}/${cfg}" ]
}

@test "workflow runs the bats suite directory, which exists" {
  grep -qE "bats tests/" "$WF"
  [ -d "${ROOT}/tests" ]
}

@test "act test-case fixtures exist" {
  [ -f "${ROOT}/tests/cases/all-expired.json" ]
  [ -f "${ROOT}/tests/cases/all-ok.json" ]
}

